import{_ as n,C as o,c as a,o as d,a3 as s,G as r}from"./chunks/framework.Dokpd4od.js";const m=JSON.parse('{"title":"Transfers","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/operations/index.md","filePath":"master/supply-chain/inventories/operations/index.md","lastUpdated":1791902625000}'),i={name:"master/supply-chain/inventories/operations/index.md"};function g(l,t,h,p,c,u){const e=o("ImagePopup");return d(),a("div",null,[t[0]||(t[0]=s(`<h1 id="transfers" tabindex="-1">Transfers <a class="header-anchor" href="#transfers" aria-label="Permalink to &quot;Transfers&quot;">​</a></h1><p>Every movement of stock in Aureus is a transfer. A receipt, a delivery, an internal move and a dropship all use the same screen, the same states and the same buttons. Learn it once and you can run all four.</p><blockquote><p><strong>In simple words:</strong> A transfer is a document that says &quot;move these products from here to there&quot;. You check it, then click <strong>Validate</strong> to make the stock really move.</p></blockquote><p>Open <code>Inventory → Operations → Transfers</code>. The <strong>Operations</strong> sidebar has two groups. <strong>Transfers</strong> holds <strong>Receipts</strong>, <strong>Deliveries</strong>, <strong>Internal Transfers</strong> and <strong>Dropships</strong>. <strong>Adjustments</strong> holds <strong>Quantities</strong> and <strong>Scraps</strong>.</p><h2 id="the-four-transfer-types" tabindex="-1">The four transfer types <a class="header-anchor" href="#the-four-transfer-types" aria-label="Permalink to &quot;The four transfer types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu item</th><th>Used for</th><th>Moves stock</th><th>Prefix</th></tr></thead><tbody><tr><td><strong>Receipts</strong></td><td>Goods coming in from vendors</td><td>Partners/Vendors to your warehouse</td><td>IN</td></tr><tr><td><strong>Deliveries</strong></td><td>Goods going out to customers</td><td>Your warehouse to Partners/Customers</td><td>OUT</td></tr><tr><td><strong>Internal Transfers</strong></td><td>Moves inside your site</td><td>One location to another</td><td>PICK, PACK, STOR, QC, INT</td></tr><tr><td><strong>Dropships</strong></td><td>Vendor ships straight to the customer</td><td>Vendors to Customers</td><td>DS</td></tr></tbody></table><p>Internal Transfers needs <strong>Locations</strong> on. Dropships needs <strong>Dropshipping</strong> on. See <a href="./../get-started/inventory-settings.html">Inventory settings</a>.</p><p>Numbers come from one shared counter, so a warehouse can show <strong>WH/IN/11</strong>, <strong>WH/IN/12</strong> and <strong>WH/OUT/42</strong>. Other prefixes in the dev data are <strong>WH/PICK</strong>, <strong>WH/PACK</strong>, <strong>WH/STOR</strong>, <strong>WH/QC</strong> and <strong>WH/PC</strong> for manufacturing components. Point of sale uses <strong>WH/POS</strong> and <strong>WH/POSRET</strong>.</p><h2 id="the-life-of-a-transfer" tabindex="-1">The life of a transfer <a class="header-anchor" href="#the-life-of-a-transfer" aria-label="Permalink to &quot;The life of a transfer&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Draft ──&gt; Waiting ──&gt; Ready ──&gt; Done</span></span>
<span class="line"><span>   \\         \\          \\</span></span>
<span class="line"><span>    └─────────┴──────────┴──&gt; Cancelled</span></span></code></pre></div><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th><th>What moves it on</th></tr></thead><tbody><tr><td><strong>Draft</strong></td><td>Created but not confirmed. Nothing is reserved.</td><td><strong>Mark as Todo</strong>. It goes to <strong>Waiting</strong>, or straight to <strong>Ready</strong> when stock is available.</td></tr><tr><td><strong>Waiting</strong></td><td>Confirmed, but some stock is not yet available.</td><td>Stock arrives, or <strong>Check Availability</strong></td></tr><tr><td><strong>Ready</strong></td><td>All stock is reserved and can be processed.</td><td><strong>Validate</strong></td></tr><tr><td><strong>Done</strong></td><td>The stock has moved.</td><td>Nothing, except <strong>Return</strong></td></tr><tr><td><strong>Canceled</strong></td><td>Stopped. No stock moved.</td><td>Nothing</td></tr></tbody></table><p>The state bar at the top of a record shows <strong>Draft</strong>, <strong>Waiting</strong>, <strong>Ready</strong>, <strong>Done</strong> and <strong>Canceled</strong>. The current state is highlighted.</p><p>A transfer created from an order starts as <strong>Waiting</strong> or <strong>Ready</strong>. You rarely see <strong>Draft</strong>.</p><h2 id="buttons-by-state" tabindex="-1">Buttons by state <a class="header-anchor" href="#buttons-by-state" aria-label="Permalink to &quot;Buttons by state&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Button</th><th>Draft</th><th>Waiting</th><th>Ready</th><th>Done</th><th>Canceled</th></tr></thead><tbody><tr><td><strong>Mark as Todo</strong></td><td>Yes</td><td>-</td><td>-</td><td>-</td><td>-</td></tr><tr><td><strong>Check Availability</strong></td><td>-</td><td>Yes</td><td>-</td><td>-</td><td>-</td></tr><tr><td><strong>Validate</strong></td><td>Yes</td><td>Yes</td><td>Yes</td><td>Hidden</td><td>Hidden</td></tr><tr><td><strong>Cancel</strong></td><td>Yes</td><td>Yes</td><td>Yes</td><td>Hidden</td><td>Hidden</td></tr><tr><td><strong>Return</strong></td><td>-</td><td>-</td><td>-</td><td>Yes</td><td>-</td></tr><tr><td><strong>Next Transfer</strong></td><td>-</td><td>-</td><td>-</td><td>Yes, if a next step exists</td><td>-</td></tr><tr><td><strong>Print</strong></td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td><strong>Delete</strong></td><td>Yes</td><td>Yes</td><td>Yes</td><td>Hidden</td><td>Yes</td></tr></tbody></table><p><strong>Check Availability</strong> shows only on <strong>Waiting</strong> transfers, such as a delivery whose source location has no stock yet. A <strong>Ready</strong> transfer does not show it. On a <strong>Done</strong> delivery, only <strong>Return</strong> and <strong>Print</strong> remain. A <strong>Canceled</strong> transfer shows only <strong>Print</strong> and <strong>Delete</strong>.</p>`,16)),r(e,{src:"/images1/inventory/ov_ready_buttons.png",alt:"Receipt WH/IN/11 in Ready state with Validate, Cancel, Print and Delete buttons"}),t[1]||(t[1]=s('<h2 id="the-record-page" tabindex="-1">The record page <a class="header-anchor" href="#the-record-page" aria-label="Permalink to &quot;The record page&quot;">​</a></h2><p>Each record has a switcher at the top with three tabs: <strong>View</strong>, <strong>Edit</strong> and <strong>Moves</strong>. <strong>Moves</strong> lists the stock move lines with product, lot, package, from, to and quantity.</p><p>The form has a <strong>General</strong> section (contact, operation type, locations) and three tabs: <strong>Operations</strong>, <strong>Additional</strong> and <strong>Note</strong>. After you click <strong>Create</strong> on a new transfer, you stay on the <strong>Edit</strong> page. The <strong>Operations</strong> table lists each product with <strong>Demand</strong>, <strong>Quantity</strong> and <strong>Picked</strong>. See <a href="./stock-moves-and-lots.html">Stock moves and lots</a>.</p><h2 id="the-list-page" tabindex="-1">The list page <a class="header-anchor" href="#the-list-page" aria-label="Permalink to &quot;The list page&quot;">​</a></h2><p>Preset tabs sit above every list: <strong>Default</strong>, <strong>To Do</strong>, <strong>My Transfers</strong>, <strong>Starred</strong>, <strong>Draft</strong>, <strong>Waiting</strong>, <strong>Ready</strong>, <strong>Late</strong> and <strong>Done</strong>. <strong>Late</strong> shows transfers past their scheduled date.</p><ul><li><strong>Columns:</strong> <strong>Favorite</strong>, <strong>Reference</strong>, <strong>Contact</strong>, <strong>Scheduled At</strong>, <strong>Source Document</strong>, <strong>Company</strong>, <strong>State</strong>. The column manager adds <strong>From</strong>, <strong>To</strong>, <strong>Responsible</strong>, <strong>Deadline</strong>, <strong>Closed At</strong> and <strong>Operation Type</strong>.</li><li><strong>Group by:</strong> <strong>State</strong>, <strong>Source Document</strong>, <strong>Operation Type</strong>, <strong>Schedule At</strong> and <strong>Created At</strong>.</li><li><strong>Filters:</strong> build rules on fields such as operation type, state, partner, locations and dates, then click <strong>Apply filters</strong>.</li></ul>',6)),r(e,{src:"/images1/inventory/ov_receipts_list.png",alt:"Receipts list with preset tabs and Ready and Done badges"}),t[2]||(t[2]=s('<h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><ul><li><a href="./receipts.html">Receipts</a> and <a href="./deliveries.html">Deliveries</a>: the two main flows.</li><li><a href="./internal-transfers.html">Internal transfers</a> and <a href="./dropships.html">Dropships</a>.</li><li><a href="./stock-moves-and-lots.html">Stock moves and lots</a>: the move lines inside a transfer.</li><li><a href="./backorders-and-returns.html">Backorders and returns</a>.</li><li><a href="./print-documents.html">Print documents</a>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../warehouses/operation-types.html">Operation types</a></li><li><a href="./../routes/">Routes</a></li><li><a href="./../adjustments/inventory-adjustments.html">Inventory adjustments</a></li></ul>',4))])}const y=n(i,[["render",g]]);export{m as __pageData,y as default};
